package provider

import "testing"

func TestSameWidgetConfig(t *testing.T) {
	cases := []struct {
		a, b string
		same bool
	}{
		{`{"source":"logs","groupBy":"service.name"}`, `{"groupBy":"service.name","source":"logs"}`, true},
		{`{"markdown":"hi"}`, `{"filter":{},"markdown":"hi"}`, true},
		{`{"source":"logs","limit":10}`, `{"source":"logs","limit":10.0}`, true},
		{`{"source":"logs"}`, `{"source":"traces"}`, false},
		{`{"filter":{"resourceAttrs":[{"key":"a","value":"b"}]}}`, `{"filter":{"resourceAttrs":[]}}`, false},
		{`not json`, `not json`, true},
	}
	for _, c := range cases {
		if got := sameWidgetConfig(c.a, c.b); got != c.same {
			t.Errorf("sameWidgetConfig(%s, %s) = %v, want %v", c.a, c.b, got, c.same)
		}
	}
}

func TestCompactJSONSortsKeys(t *testing.T) {
	if got := compactJSON([]byte(`{ "b": 1, "a": {"d": 2, "c": 3}, "filter": {}, "x": null }`)); got != `{"a":{"c":3,"d":2},"b":1}` {
		t.Errorf("compactJSON = %s", got)
	}
}

package provider

import (
	"os"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/providerserver"
	"github.com/hashicorp/terraform-plugin-go/tfprotov6"
)

// Acceptance tests create real objects. Run them with TF_ACC=1 and
// SUPERLOG_API_KEY (and SUPERLOG_ENDPOINT for a local or US workspace) set.
var testProviders = map[string]func() (tfprotov6.ProviderServer, error){
	"superlog": providerserver.NewProtocol6WithError(New("test")()),
}

func testPreCheck(t *testing.T) {
	if os.Getenv("SUPERLOG_API_KEY") == "" {
		t.Fatal("SUPERLOG_API_KEY must be set for acceptance tests")
	}
}

package client

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestErrorsIncludeIssues(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("Authorization") != "Bearer slk_test" {
			t.Errorf("missing bearer token")
		}
		w.WriteHeader(http.StatusBadRequest)
		_ = json.NewEncoder(w).Encode(map[string]any{
			"code":   "invalid_request",
			"error":  "Invalid widget",
			"issues": []map[string]any{{"message": "Choose a metric", "path": []any{"widgets", 1, "config", "metricName"}}},
		})
	}))
	defer server.Close()
	c, err := New(server.URL, "slk_test", "test")
	if err != nil {
		t.Fatal(err)
	}
	_, err = c.CreateDashboard(context.Background(), DashboardInput{Name: "x"})
	if err == nil || !strings.Contains(err.Error(), "widgets.1.config.metricName: Choose a metric") {
		t.Fatalf("unexpected error: %v", err)
	}
	if IsNotFound(err) {
		t.Fatal("a 400 is not a not-found")
	}
}

func TestNotFoundNeedsAnObjectCode(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusNotFound)
		code := "alert_not_found"
		if strings.HasPrefix(r.URL.Path, "/api/v1/dashboards") {
			// The feature is off: the object may still exist.
			code = "dashboards_unavailable"
		}
		_ = json.NewEncoder(w).Encode(map[string]any{"code": code, "error": "x"})
	}))
	defer server.Close()
	c, _ := New(server.URL, "slk_test", "test")
	if _, err := c.GetAlert(context.Background(), "a"); !IsNotFound(err) {
		t.Fatalf("expected not found, got %v", err)
	}
	if _, err := c.GetDashboard(context.Background(), "d"); IsNotFound(err) {
		t.Fatal("an unavailable feature must not read as a deleted dashboard")
	}
}

func TestEndpointMustBeAURL(t *testing.T) {
	if _, err := New("superlog.sh", "k", "test"); err == nil {
		t.Fatal("expected an error for an endpoint without a scheme")
	}
	c, err := New("", "k", "test")
	if err != nil || c.baseURL != "https://superlog.sh/api/v1" {
		t.Fatalf("default endpoint: %v %v", c, err)
	}
}

package provider

import (
	"fmt"
	"testing"

	"github.com/hashicorp/terraform-plugin-testing/helper/acctest"
	"github.com/hashicorp/terraform-plugin-testing/helper/resource"
)

func TestAccAlert(t *testing.T) {
	name := acctest.RandomWithPrefix("tf-acc")
	config := func(threshold int) string {
		return fmt.Sprintf(`
resource "superlog_alert" "test" {
  name        = %q
  source      = "logs"
  aggregation = "count"
  comparator  = "gt"
  threshold   = %d
  filter = {
    service    = "checkout"
    attributes = [{ key = "deployment.environment", op = "neq", value = "staging" }]
  }
}`, name, threshold)
	}
	resource.Test(t, resource.TestCase{
		PreCheck:                 func() { testPreCheck(t) },
		ProtoV6ProviderFactories: testProviders,
		Steps: []resource.TestStep{
			{
				Config: config(50),
				Check: resource.ComposeAggregateTestCheckFunc(
					resource.TestCheckResourceAttr("superlog_alert.test", "threshold", "50"),
					resource.TestCheckResourceAttr("superlog_alert.test", "window_minutes", "5"),
					resource.TestCheckResourceAttrSet("superlog_alert.test", "url"),
				),
			},
			{Config: config(80), Check: resource.TestCheckResourceAttr("superlog_alert.test", "threshold", "80")},
			{ResourceName: "superlog_alert.test", ImportState: true, ImportStateVerify: true},
		},
	})
}

func TestAccDashboard(t *testing.T) {
	name := acctest.RandomWithPrefix("tf-acc")
	errors := `{
      title  = "Errors"
      type   = "timeseries_count"
      config = jsonencode({ source = "logs", groupBy = "service.name", filter = { resourceAttrs = [{ key = "deployment.environment", value = "$${env}" }] } })
      layout = { x = 0, y = 0, w = 6, h = 4 }
    }`
	notes := `{
      title  = "Notes"
      type   = "markdown"
      config = jsonencode({ markdown = "Runbook" })
      layout = { x = 6, y = 0, w = 6, h = 4 }
    }`
	config := func(widgets string) string {
		return fmt.Sprintf(`
resource "superlog_dashboard" "test" {
  name      = %q
  variables = [{ name = "env", options = ["prod", "staging"], default_value = "prod" }]
  widgets   = [%s]
}`, name, widgets)
	}
	resource.Test(t, resource.TestCase{
		PreCheck:                 func() { testPreCheck(t) },
		ProtoV6ProviderFactories: testProviders,
		Steps: []resource.TestStep{
			{
				Config: config(errors + "," + notes),
				Check: resource.ComposeAggregateTestCheckFunc(
					resource.TestCheckResourceAttr("superlog_dashboard.test", "widgets.#", "2"),
					resource.TestCheckResourceAttr("superlog_dashboard.test", "widgets.1.title", "Notes"),
				),
			},
			{
				Config: config(notes),
				Check: resource.ComposeAggregateTestCheckFunc(
					resource.TestCheckResourceAttr("superlog_dashboard.test", "widgets.#", "1"),
					resource.TestCheckResourceAttr("superlog_dashboard.test", "widgets.0.title", "Notes"),
				),
			},
			{ResourceName: "superlog_dashboard.test", ImportState: true, ImportStateVerify: true},
		},
	})
}

func TestAccSyntheticCheck(t *testing.T) {
	name := acctest.RandomWithPrefix("tf-acc")
	config := func(token string) string {
		return fmt.Sprintf(`
resource "superlog_synthetic_check" "test" {
  name             = %q
  url              = "https://example.com/health"
  interval_seconds = 900
  headers          = { Accept = "application/json" }
  secret_headers   = { Authorization = %q }
  assertions = [
    { kind = "status_code", op = "eq", value = "2xx" },
    { kind = "response_time", op = "lt", value = "1500", severity = "degraded" },
  ]
}`, name, token)
	}
	resource.Test(t, resource.TestCase{
		PreCheck:                 func() { testPreCheck(t) },
		ProtoV6ProviderFactories: testProviders,
		Steps: []resource.TestStep{
			{
				Config: config("Bearer one"),
				Check: resource.ComposeAggregateTestCheckFunc(
					resource.TestCheckResourceAttr("superlog_synthetic_check.test", "method", "GET"),
					resource.TestCheckResourceAttr("superlog_synthetic_check.test", "assertions.0.severity", "critical"),
					resource.TestCheckResourceAttr("superlog_synthetic_check.test", "secret_headers.Authorization", "Bearer one"),
				),
			},
			{Config: config("Bearer two"), Check: resource.TestCheckResourceAttr("superlog_synthetic_check.test", "secret_headers.Authorization", "Bearer two")},
			{
				ResourceName:      "superlog_synthetic_check.test",
				ImportState:       true,
				ImportStateVerify: true,
				// Superlog never returns secret header values.
				ImportStateVerifyIgnore: []string{"secret_headers.Authorization"},
			},
		},
	})
}

