// Package client calls the Superlog management API.
package client

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"
)

// DefaultEndpoint is the EU cell. The US cell is https://us.superlog.sh.
const DefaultEndpoint = "https://superlog.sh"

type Client struct {
	apiKey    string
	baseURL   string
	http      *http.Client
	userAgent string
}

func New(endpoint, apiKey, userAgent string) (*Client, error) {
	if endpoint == "" {
		endpoint = DefaultEndpoint
	}
	parsed, err := url.Parse(endpoint)
	if err != nil || (parsed.Scheme != "https" && parsed.Scheme != "http") || parsed.Host == "" {
		return nil, fmt.Errorf("endpoint must be an HTTP or HTTPS URL, such as %s", DefaultEndpoint)
	}
	return &Client{
		apiKey:    apiKey,
		baseURL:   strings.TrimRight(endpoint, "/") + "/api/v1",
		http:      &http.Client{Timeout: 60 * time.Second},
		userAgent: userAgent,
	}, nil
}

// Error is a failed API response.
type Error struct {
	Status  int
	Code    string `json:"code"`
	Message string `json:"error"`
	Issues  []struct {
		Message string `json:"message"`
		Path    []any  `json:"path"`
	} `json:"issues"`
}

func (e *Error) Error() string {
	message := e.Message
	if message == "" {
		message = http.StatusText(e.Status)
	}
	parts := []string{fmt.Sprintf("%s (HTTP %d", message, e.Status)}
	if e.Code != "" {
		parts[0] += ", " + e.Code
	}
	parts[0] += ")"
	for _, issue := range e.Issues {
		path := make([]string, len(issue.Path))
		for i, part := range issue.Path {
			path[i] = fmt.Sprint(part)
		}
		if len(path) > 0 {
			parts = append(parts, fmt.Sprintf("%s: %s", strings.Join(path, "."), issue.Message))
		} else {
			parts = append(parts, issue.Message)
		}
	}
	return strings.Join(parts, "\n")
}

// IsNotFound reports whether the object no longer exists.
func IsNotFound(err error) bool {
	var apiErr *Error
	return errors.As(err, &apiErr) && apiErr.Status == http.StatusNotFound &&
		strings.HasSuffix(apiErr.Code, "_not_found")
}

func (c *Client) do(ctx context.Context, method, path string, body, out any) error {
	var reader io.Reader
	if body != nil {
		encoded, err := json.Marshal(body)
		if err != nil {
			return err
		}
		reader = bytes.NewReader(encoded)
	}
	request, err := http.NewRequestWithContext(ctx, method, c.baseURL+path, reader)
	if err != nil {
		return err
	}
	request.Header.Set("Authorization", "Bearer "+c.apiKey)
	request.Header.Set("Accept", "application/json")
	request.Header.Set("User-Agent", c.userAgent)
	if body != nil {
		request.Header.Set("Content-Type", "application/json")
	}
	response, err := c.http.Do(request)
	if err != nil {
		return err
	}
	defer response.Body.Close()
	data, err := io.ReadAll(io.LimitReader(response.Body, 32<<20))
	if err != nil {
		return err
	}
	if response.StatusCode >= 300 {
		apiErr := &Error{Status: response.StatusCode}
		_ = json.Unmarshal(data, apiErr)
		return apiErr
	}
	if out == nil {
		return nil
	}
	if err := json.Unmarshal(data, out); err != nil {
		return fmt.Errorf("reading the %s %s response: %w", method, path, err)
	}
	return nil
}

func escape(id string) string { return url.PathEscape(id) }

// Package provider is the Superlog Terraform provider.
package provider

import (
	"context"
	"os"

	"github.com/hashicorp/terraform-plugin-framework/datasource"
	"github.com/hashicorp/terraform-plugin-framework/path"
	"github.com/hashicorp/terraform-plugin-framework/provider"
	"github.com/hashicorp/terraform-plugin-framework/provider/schema"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/types"
	"github.com/superloglabs/terraform-provider-superlog/internal/client"
)

type superlogProvider struct {
	version string
}

type providerModel struct {
	APIKey   types.String `tfsdk:"api_key"`
	Endpoint types.String `tfsdk:"endpoint"`
}

func New(version string) func() provider.Provider {
	return func() provider.Provider { return &superlogProvider{version: version} }
}

func (p *superlogProvider) Metadata(_ context.Context, _ provider.MetadataRequest, resp *provider.MetadataResponse) {
	resp.TypeName = "superlog"
	resp.Version = p.version
}

func (p *superlogProvider) Schema(_ context.Context, _ provider.SchemaRequest, resp *provider.SchemaResponse) {
	resp.Schema = schema.Schema{
		MarkdownDescription: "Manage Superlog alerts, dashboards, and synthetic checks. Create an API key in Superlog under Settings → API keys. The provider acts as the member who created the key, in that key's workspace.",
		Attributes: map[string]schema.Attribute{
			"api_key": [REDACTED]
				MarkdownDescription: "A Superlog API key. Can also be set with the `SUPERLOG_API_KEY` environment variable.",
				Optional:            true,
				Sensitive:           true,
			},
			"endpoint": schema.StringAttribute{
				MarkdownDescription: "The Superlog URL: `https://superlog.sh` for the EU region (the default) or `https://us.superlog.sh` for the US region. Can also be set with the `SUPERLOG_ENDPOINT` environment variable.",
				Optional:            true,
			},
		},
	}
}

func (p *superlogProvider) Configure(ctx context.Context, req provider.ConfigureRequest, resp *provider.ConfigureResponse) {
	var config providerModel
	resp.Diagnostics.Append(req.Config.Get(ctx, &config)...)
	if resp.Diagnostics.HasError() {
		return
	}
	if config.APIKey.IsUnknown() || config.Endpoint.IsUnknown() {
		// Known at apply time; the provider is configured again then.
		return
	}
	apiKey := os.Getenv("SUPERLOG_API_KEY")
	if !config.APIKey.IsNull() {
		apiKey = [REDACTED]
	}
	endpoint := os.Getenv("SUPERLOG_ENDPOINT")
	if !config.Endpoint.IsNull() {
		endpoint = config.Endpoint.ValueString()
	}
	if apiKey == "" {
		resp.Diagnostics.AddAttributeError(path.Root("api_key"), "Missing API key",
			"Set api_key in the provider block or the SUPERLOG_API_KEY environment variable. Create a key in Superlog under Settings → API keys.")
		return
	}
	c, err := client.New(endpoint, apiKey, "terraform-provider-superlog/"+p.version)
	if err != nil {
		resp.Diagnostics.AddAttributeError(path.Root("endpoint"), "Invalid endpoint", err.Error())
		return
	}
	resp.ResourceData = c
	resp.DataSourceData = c
}

func (p *superlogProvider) Resources(_ context.Context) []func() resource.Resource {
	return []func() resource.Resource{
		newAlertResource,
		newDashboardResource,
		newSyntheticCheckResource,
	}
}

func (p *superlogProvider) DataSources(_ context.Context) []func() datasource.DataSource {
	return []func() datasource.DataSource{
		newSlackChannelDataSource,
	}
}

package provider

import (
	"context"
	"fmt"
	"strings"

	"github.com/hashicorp/terraform-plugin-framework/datasource"
	"github.com/hashicorp/terraform-plugin-framework/datasource/schema"
	"github.com/hashicorp/terraform-plugin-framework/types"
	"github.com/superloglabs/terraform-provider-superlog/internal/client"
)

var _ datasource.DataSourceWithConfigure = &slackChannelDataSource{}

type slackChannelDataSource struct {
	client *client.Client
}

type slackChannelModel struct {
	ChannelID            types.String `tfsdk:"channel_id"`
	IntegrationAccountID types.String `tfsdk:"integration_account_id"`
	Name                 types.String `tfsdk:"name"`
	Private              types.Bool   `tfsdk:"private"`
	Workspace            types.String `tfsdk:"workspace"`
}

func newSlackChannelDataSource() datasource.DataSource { return &slackChannelDataSource{} }

func (d *slackChannelDataSource) Metadata(_ context.Context, req datasource.MetadataRequest, resp *datasource.MetadataResponse) {
	resp.TypeName = req.ProviderTypeName + "_slack_channel"
}

func (d *slackChannelDataSource) Schema(_ context.Context, _ datasource.SchemaRequest, resp *datasource.SchemaResponse) {
	resp.Schema = schema.Schema{
		MarkdownDescription: "A Slack channel alerts and synthetic checks can post to: a public channel, or a private channel the Superlog app is in.",
		Attributes: map[string]schema.Attribute{
			"name": schema.StringAttribute{
				MarkdownDescription: "The channel name, with or without `#`.",
				Required:            true,
			},
			"workspace": schema.StringAttribute{
				MarkdownDescription: "The Slack workspace's name. Needed when more than one connected workspace has a channel with this name.",
				Optional:            true,
				Computed:            true,
			},
			"channel_id":             schema.StringAttribute{Computed: true},
			"integration_account_id": schema.StringAttribute{Computed: true},
			"private":                schema.BoolAttribute{Computed: true},
		},
	}
}

func (d *slackChannelDataSource) Configure(_ context.Context, req datasource.ConfigureRequest, resp *datasource.ConfigureResponse) {
	d.client = configuredClient(req.ProviderData, &resp.Diagnostics)
}

func (d *slackChannelDataSource) Read(ctx context.Context, req datasource.ReadRequest, resp *datasource.ReadResponse) {
	var config slackChannelModel
	resp.Diagnostics.Append(req.Config.Get(ctx, &config)...)
	if resp.Diagnostics.HasError() {
		return
	}
	channels, err := d.client.ListSlackChannels(ctx)
	if err != nil {
		resp.Diagnostics.AddError("Unable to list Slack channels", err.Error())
		return
	}
	name := strings.TrimPrefix(config.Name.ValueString(), "#")
	var matches []client.SlackChannel
	for _, channel := range channels {
		if channel.Name != name {
			continue
		}
		if !config.Workspace.IsNull() && !config.Workspace.IsUnknown() && channel.AccountName != config.Workspace.ValueString() {
			continue
		}
		matches = append(matches, channel)
	}
	switch len(matches) {
	case 0:
		resp.Diagnostics.AddError("Slack channel not found", fmt.Sprintf(
			"No connected Slack workspace has a channel #%s Superlog can post to. For a private channel, invite the Superlog app first. New channels can take a few minutes to appear.", name))
		return
	case 1:
	default:
		resp.Diagnostics.AddError("More than one Slack channel matches", fmt.Sprintf(
			"More than one connected Slack workspace has #%s. Set workspace to choose one.", name))
		return
	}
	channel := matches[0]
	resp.Diagnostics.Append(resp.State.Set(ctx, slackChannelModel{
		ChannelID:            types.StringValue(channel.ChannelID),
		IntegrationAccountID: types.StringValue(channel.IntegrationAccountID),
		Name:                 config.Name,
		Private:              types.BoolValue(channel.Private),
		Workspace:            types.StringValue(channel.AccountName),
	})...)
}

package client

import (
	"context"
	"encoding/json"
	"net/http"
)

type SlackTarget struct {
	ChannelID            string `json:"channelId"`
	IntegrationAccountID string `json:"integrationAccountId"`
}

type AttributeFilter struct {
	Key   string  `json:"key"`
	Op    *string `json:"op,omitempty"`
	Value string  `json:"value"`
}

type AlertFilter struct {
	MetricKind    *string           `json:"metricKind,omitempty"`
	MetricUnit    *string           `json:"metricUnit,omitempty"`
	MinDurationMs *float64          `json:"minDurationMs,omitempty"`
	ResourceAttrs []AttributeFilter `json:"resourceAttrs,omitempty"`
	Service       *string           `json:"service,omitempty"`
	Severity      *string           `json:"severity,omitempty"`
	SpanName      *string           `json:"spanName,omitempty"`
	StatusCode    *string           `json:"statusCode,omitempty"`
}

// AlertInput is every field of an alert a client sets.
type AlertInput struct {
	Aggregation               string       `json:"aggregation"`
	Comparator                string       `json:"comparator"`
	Enabled                   bool         `json:"enabled"`
	EvaluationIntervalSeconds int64        `json:"evaluationIntervalSeconds"`
	Field                     *string      `json:"field"`
	Filter                    AlertFilter  `json:"filter"`
	GroupBy                   *string      `json:"groupBy"`
	GroupMode                 string       `json:"groupMode"`
	MetricName                *string      `json:"metricName"`
	Name                      string       `json:"name"`
	Slack                     *SlackTarget `json:"slack"`
	Source                    string       `json:"source"`
	Threshold                 float64      `json:"threshold"`
	WindowMinutes             int64        `json:"windowMinutes"`
}

type Alert struct {
	AlertInput
	ID  string `json:"id"`
	URL string `json:"url"`
}

func (c *Client) ListAlerts(ctx context.Context) ([]Alert, error) {
	var out struct {
		Alerts []Alert `json:"alerts"`
	}
	err := c.do(ctx, http.MethodGet, "/alerts", nil, &out)
	return out.Alerts, err
}

func (c *Client) GetAlert(ctx context.Context, id string) (*Alert, error) {
	var out struct {
		Alert Alert `json:"alert"`
	}
	if err := c.do(ctx, http.MethodGet, "/alerts/"+escape(id), nil, &out); err != nil {
		return nil, err
	}
	return &out.Alert, nil
}

func (c *Client) CreateAlert(ctx context.Context, input AlertInput) (*Alert, error) {
	var out struct {
		Alert Alert `json:"alert"`
	}
	if err := c.do(ctx, http.MethodPost, "/alerts", input, &out); err != nil {
		return nil, err
	}
	return &out.Alert, nil
}

func (c *Client) UpdateAlert(ctx context.Context, id string, input AlertInput) (*Alert, error) {
	var out struct {
		Alert Alert `json:"alert"`
	}
	if err := c.do(ctx, http.MethodPatch, "/alerts/"+escape(id), input, &out); err != nil {
		return nil, err
	}
	return &out.Alert, nil
}

func (c *Client) DeleteAlert(ctx context.Context, id string) error {
	return c.do(ctx, http.MethodDelete, "/alerts/"+escape(id), nil, nil)
}

type DashboardVariable struct {
	AttributeKey *string  `json:"attributeKey,omitempty"`
	DefaultValue *string  `json:"defaultValue,omitempty"`
	Label        *string  `json:"label,omitempty"`
	Multi        *bool    `json:"multi,omitempty"`
	Name         string   `json:"name"`
	Options      []string `json:"options"`
}

type WidgetLayout struct {
